<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { BookOpen, FolderOpen, Library, FileText, ArrowRight, Download, Bookmark, ThumbsUp, Search, Plus, History, ShieldCheck } from 'lucide-vue-next'
import { api, send, upload, date, type Board } from '../api'
import { useSession } from '../store'
import RichContent from './RichContent.vue'
type Row = Record<string, any>
type Page = { items: Row[]; hasNext: boolean }
const route=useRoute(),router=useRouter(),session=useSession()
const isAdmin=route.path.startsWith('/admin/'),kind=String(route.path.split('/')[isAdmin?2:1]),id=Number(route.params.id || 0)
const wiki=kind==='wiki',isNew=route.path.endsWith('/new')
const labels:Record<string,string>={resources:'资料库',mistakes:'错题本',notes:'学习笔记',collections:'专题合集',columns:'连载专栏',wiki:'板块 Wiki'}
const intros:Record<string,string>={resources:'把值得分享的资料，留给下一位认真学习的人。',mistakes:'从每一次错误中，找到下一次进步的线索。',notes:'整理思路、记录理解，让知识真正成为自己的。',collections:'将零散的讨论与资源，整理成一条清晰的学习路径。',columns:'用一篇篇长文，持续讲透一个主题。',wiki:'由板块维护者共同整理的常见问题、术语与学习路线。'}
const icons:Record<string,any>={resources:FolderOpen,mistakes:BookOpen,notes:FileText,collections:Library,columns:BookOpen,wiki:Library}
const statuses:Record<string,string>={pending:'待审核',published:'已发布',rejected:'已拒绝 / 下架',draft:'草稿',active:'正常',disabled:'已停用',public:'公开',private:'仅自己',group:'小组共享'}
const boards=ref<Board[]>([]),groups=ref<Row[]>([]),items=ref<Row[]>([]),detail=ref<Row|null>(null),loading=ref(false),busy=ref(false),error=ref(''),page=ref(1),hasNext=ref(false)
const boardId=ref(Number(route.params.boardId)||0),canWikiEdit=ref(false),editorOpen=ref(isNew),editingId=ref(0),baseRevision=ref(0),history=ref<Row[]>([]),historyOpen=ref(false)
const filters=reactive({q:String(route.query.q||''),subject:'',grade:'',textbook:'',exam:'',mine:false,favorite:false,scope:'mine',due:false,featured:route.query.featured==='true',following:false})
const form=reactive<Row>({}),files=ref<Row[]>([]),stats=ref<Row|null>(null),selected=ref<number[]>([]),reviewDays=ref(7),downloadFiles=ref<Row[]>([]),comment=ref(''),reportOpen=ref(false),reportReason=ref('抄袭侵权'),reportDescription=ref(''),episodeOpen=ref(false),episodeEditingId=ref(0)
const downloadsOpen=ref(false),downloads=ref<Row[]>([])
async function showDownloads(){if(!login())return;await run(async()=>{downloads.value=await api('/resources/downloads');downloadsOpen.value=!downloadsOpen.value})}
const episode=reactive({title:'',content:'',episodeNo:1,status:'published',noteId:0}),notesOptions=ref<Row[]>([])
const picker=reactive({type:'post',q:'',id:0,sortOrder:0}),choices=ref<Row[]>([]),pickerOpen=ref(false),moderationNotes=reactive<Record<number,string>>({})
const owner=computed(()=>!!detail.value && Number(detail.value[kind==='notes'||kind==='mistakes'?'user_id':kind==='resources'?'uploader_id':'owner_id'])===session.user?.id)
const allowedAdmin=computed(()=>session.user?.role==='admin'||kind==='wiki'&&session.user?.role==='moderator')
function login(){if(session.user)return true;router.push({path:'/login',query:{next:route.fullPath}});return false}
async function run(task:()=>Promise<void>,message=''){
 if(busy.value)return;busy.value=true;error.value=''
 try{await task();if(message)ElMessage.success(message)}catch(e){error.value=(e as Error).message}finally{busy.value=false}
}
async function load(){
 loading.value=true;error.value='';history.value=[];historyOpen.value=false
 try{
  if(isAdmin){if(!allowedAdmin.value)return;const result=await api<Page>('/admin/'+kind+'?page='+page.value);items.value=result.items;hasNext.value=result.hasNext;return}
  if(wiki){if(!boardId.value)return;const result=await api<Row>('/wiki/'+boardId.value+'?q='+encodeURIComponent(filters.q));items.value=result.items;canWikiEdit.value=result.canEdit;return}
  if(id){detail.value=await api<Row>('/'+kind+'/'+id);return}
  if(kind==='mistakes'&&!session.user){filters.scope='public'}
  const params=new URLSearchParams({page:String(page.value),q:filters.q,subject:filters.subject})
  if(kind==='mistakes'){params.set('scope',filters.scope);params.set('due',String(filters.due))}
  else params.set('mine',String(filters.mine))
  if(kind==='resources'){for(const key of ['grade','textbook','exam'] as const)params.set(key,filters[key]);params.set('favorite',String(filters.favorite))}
  if(kind==='collections'){params.set('featured',String(filters.featured));params.set('favorite',String(filters.favorite));params.set('following',String(filters.following))}
  const result=await api<Page>('/'+kind+'?'+params);items.value=result.items;hasNext.value=result.hasNext
  if(kind==='mistakes'&&session.user)stats.value=await api('/mistakes/stats')
 }catch(e){error.value=(e as Error).message}finally{loading.value=false}
}
function resetForm(row?:Row){
 for(const key of Object.keys(form))delete form[key]
 Object.assign(form,{title:'',description:'',subject:'',grade:'',textbook:'',exam:'',tags:'',source:'',copyrightNote:'',downloadPoints:0,integrityAccepted:false,question:'',answer:'',reason:'',knowledgePoint:'',visibility:'private',groupId:0,postId:Number(route.query.postId)||0,imagePath:'',content:'',status:'draft',coverUrl:''})
 files.value=[]
 if(row)Object.assign(form,row,{copyrightNote:row.copyright_note,downloadPoints:row.download_points,knowledgePoint:row.knowledge_point,groupId:row.group_id||0,postId:row.post_id||0,imagePath:row.image_path||'',coverUrl:row.cover_url||''})
 if(!row&&kind==='mistakes'){form.question=String(route.query.question||'');form.source=route.query.postId?'论坛帖子 #'+route.query.postId:''}
}
function openEditor(row?:Row){if(!login())return;resetForm(row);editingId.value=row?.id||0;editorOpen.value=true;historyOpen.value=false}
async function openWiki(row?:Row){if(!login())return;await run(async()=>{resetForm(row);editingId.value=row?.id||0;baseRevision.value=0;if(row){history.value=await api('/wiki/pages/'+row.id+'/revisions');baseRevision.value=history.value[0]?.id||0}editorOpen.value=true})}
async function save(){if(!login())return;await run(async()=>{
 const payload={...form,files:files.value.map(f=>f.id),baseRevisionId:baseRevision.value}
 const path=wiki?'/wiki/'+(editingId.value||boardId.value):'/'+kind+(editingId.value?'/'+editingId.value:'')
 const result=await send<Row>(path,editingId.value?'PATCH':'POST',payload)
 editorOpen.value=false
 if(!wiki && !editingId.value){await router.push('/'+kind+'/'+result.id)}else await load()
},kind==='resources'?'资料已提交审核':'已保存')}
async function uploadFiles(event:Event){const input=event.target as HTMLInputElement;const chosen=Array.from(input.files||[]);await run(async()=>{if(files.value.length+chosen.length>10)throw new Error('最多上传 10 个文件');for(const file of chosen){const data=new FormData();data.append('file',file);files.value.push(await api('/resources/files',{method:'POST',body:data}))}});input.value=''}
async function image(event:Event,key:string){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(file)await run(async()=>{if(key==='imagePath'){const data=new FormData();data.append('file',file);form[key]=(await api<{path:string}>('/mistakes/images',{method:'POST',body:data})).path}else form[key]=(await upload(file)).path});input.value=''}
async function action(path:string,value:object,message='已更新'){if(!login())return;await run(async()=>{await send(path,'POST',value);await load()},message)}
async function sendComment(){if(!login())return;await run(async()=>{await send('/resources/'+id+'/comments','POST',{content:comment.value});comment.value='';await load()},'评论已发布')}
async function sendReport(){if(!login())return;await run(async()=>{await send('/resources/'+id+'/report','POST',{reason:reportReason.value,description:reportDescription.value});reportOpen.value=false;reportDescription.value=''},'举报已提交')}
async function download(){if(!login())return;await run(async()=>{const r=await send<Row>('/resources/'+id+'/download','POST');downloadFiles.value=r.files;await session.refresh();await load()},'下载已开通，选择文件保存；重复下载不再扣积分')}
async function revisions(row?:Row){await run(async()=>{history.value=await api(wiki?'/wiki/pages/'+row?.id+'/revisions':'/notes/'+id+'/revisions');historyOpen.value=!historyOpen.value})}
async function makePlan(){if(!login())return;await run(async()=>{const result=await send<Row>('/mistakes/review-plan','POST',{ids:selected.value,days:reviewDays.value});await router.push('/plans/'+result.id)},'复习计划已生成')}
async function searchPicker(){await run(async()=>{const r=await api<Page|Row[]>(picker.type==='post'?'/search?q='+encodeURIComponent(picker.q):'/'+(picker.type==='resource'?'resources':'notes')+'?q='+encodeURIComponent(picker.q));choices.value=Array.isArray(r)?r:r.items;picker.id=0})}
async function addItem(){await run(async()=>{await send('/collections/'+id+'/items','POST',{itemType:picker.type,itemId:picker.id,sortOrder:picker.sortOrder});pickerOpen.value=false;await load()},'已收录')}
function target(item:Row){return '/'+({post:'posts',resource:'resources',note:'notes'} as Record<string,string>)[item.item_type]+'/'+item.item_id}
async function itemChange(item:Row,remove=false){await run(async()=>{await send('/collections/'+id+'/items/'+item.id,remove?'DELETE':'PATCH',remove?undefined:{sortOrder:item.sort_order});await load()},remove?'已移除':'排序已保存')}
async function openEpisode(row?:Row){if(!login())return;await run(async()=>{notesOptions.value=(await api<Page>('/notes?mine=true')).items.filter(n=>n.status==='published');episodeEditingId.value=row?.id||0;Object.assign(episode,{title:row?.title||'',content:row?.content||'',episodeNo:row?.episode_no||(detail.value?.episodes?.length||0)+1,status:row?.status||'published',noteId:0});episodeOpen.value=true})}
async function saveEpisode(){await run(async()=>{await send('/columns/'+id+'/episodes'+(episodeEditingId.value?'/'+episodeEditingId.value:''),episodeEditingId.value?'PATCH':'POST',episode);episodeOpen.value=false;await load()},'连载已保存')}
async function moderate(row:Row,status:string,featured=false){await run(async()=>{await send('/admin/'+kind+'/'+row.id,'PATCH',{status,featured,note:moderationNotes[row.id]||''});await load()},'治理操作已保存')}
async function share(){await run(async()=>{await navigator.clipboard.writeText(window.location.href)},'合集链接已复制')}
function bytes(n:number){return n>=1000000?(n/1000000).toFixed(1)+' MB':Math.ceil(n/1000)+' KB'}
async function changePage(delta:number){page.value+=delta;selected.value=[];await load()}
onMounted(async()=>{
 resetForm();if(!session.ready)await session.refresh()
 try{boards.value=await api<Board[]>('/boards');if(wiki&&!boardId.value)boardId.value=boards.value[0]?.id||0;if(kind==='mistakes'&&session.user)groups.value=await api('/mistakes/groups')}catch(e){error.value=(e as Error).message}
 await load()
})
</script>

<template>
 <section class="knowledge-page">
  <header class="knowledge-heading"><div><span class="eyebrow">同频 · 知识沉淀 <span v-if="isAdmin">/ 内容治理</span></span><h1>{{ labels[kind] }}<span v-if="isAdmin">管理</span></h1><p>{{ intros[kind] }}</p></div><component :is="icons[kind]" :size="42" :stroke-width="1.2" aria-hidden="true"/></header>
  <nav class="knowledge-nav" aria-label="知识模块"><RouterLink v-for="(label,key) in labels" :key="key" :to="'/'+key" :class="{active:kind===key}">{{ label }}</RouterLink></nav>
  <nav v-if="isAdmin" class="knowledge-nav" aria-label="知识治理"><RouterLink v-for="(label,key) in {resources:'资料审核',wiki:'Wiki 管理',collections:'合集推荐'}" :key="key" :to="'/admin/'+key">{{ label }}</RouterLink><RouterLink to="/admin">返回管理后台</RouterLink></nav>
  <p v-if="error" class="knowledge-error" role="alert">{{ error }} <button type="button" @click="load">重新加载</button></p>
  <p v-if="loading" class="knowledge-empty" role="status">正在整理知识…</p>
  <template v-if="isAdmin">
   <div v-if="!allowedAdmin" class="knowledge-empty">你没有此模块的管理权限。</div>
   <template v-else><article v-for="row in items" :key="row.id" class="knowledge-panel admin-knowledge-row">
    <div class="row-heading"><div><span class="knowledge-chip">{{ statuses[row.status] }} <span v-if="row.is_featured">· 推荐</span></span><h2>{{ row.title }}</h2><p>{{ row.username }} <span v-if="row.board_name">· {{ row.board_name }}</span></p></div><RouterLink :to="kind==='wiki'?'/wiki/'+row.board_id:'/'+kind+'/'+row.id" class="button">查看内容</RouterLink></div>
    <RichContent v-if="kind==='wiki'" :content="row.content"/>
    <p v-else>{{ row.description }}</p><p v-if="kind==='resources'" class="muted">来源：{{ row.source }} · 版权：{{ row.copyright_note }}</p>
    <div class="knowledge-actions"><label v-if="kind!=='collections'">处理说明<input v-model="moderationNotes[row.id]" required maxlength="500" placeholder="审核或下架原因"/></label>
     <button class="button primary" :disabled="busy" @click="moderate(row,kind==='collections'?'active':'published',kind==='collections')">{{ kind==='collections'?'设为推荐':'审核发布' }}</button>
     <button class="button" :disabled="busy" @click="moderate(row,kind==='collections'?'disabled':kind==='wiki'?'draft':'rejected')">{{ kind==='collections'?'停用':kind==='wiki'?'下架为草稿':'拒绝 / 下架' }}</button>
     <button v-if="kind==='collections'" class="button" :disabled="busy" @click="moderate(row,'active',false)">取消推荐 / 恢复</button>
     <button v-if="wiki" class="button" :disabled="busy" @click="revisions(row)"><History :size="15"/>版本历史</button>
    </div>
   </article><p v-if="!items.length&&!loading" class="knowledge-empty">暂无待治理内容。</p></template>
  </template>
  <template v-else>
   <div v-if="wiki" class="knowledge-panel wiki-selector"><label>学习板块<select v-model.number="boardId" @change="editorOpen=false; load()"><option v-for="board in boards" :key="board.id" :value="board.id">{{ board.name }}</option></select></label><form class="knowledge-search" @submit.prevent="load"><input v-model="filters.q" aria-label="搜索 Wiki" maxlength="100" placeholder="搜索术语、问题或学习路线"/><button class="button" :disabled="loading"><Search :size="16"/>搜索</button></form><button v-if="canWikiEdit" class="button primary" :disabled="busy" @click="openWiki()"><Plus :size="16"/>新增 Wiki</button></div>
   <div v-if="!wiki&&!id&&!isNew" class="knowledge-panel filters-panel">
    <div class="filter-top"><form class="knowledge-search" @submit.prevent="page=1; load()"><input v-model="filters.q" maxlength="100" :placeholder="kind==='mistakes'?'搜索题目、知识点或标签':'搜索标题、内容或标签'" aria-label="搜索知识内容"/><button class="button" :disabled="loading"><Search :size="16"/>搜索</button></form><button class="button primary" @click="openEditor()"><Plus :size="16"/>{{ kind==='resources'?'上传资料':kind==='mistakes'?'记录错题':'创建'+labels[kind] }}</button></div>
    <div class="knowledge-filters">
     <label v-if="['resources','mistakes','notes'].includes(kind)">学科<input v-model="filters.subject" maxlength="40" placeholder="全部学科"/></label>
     <template v-if="kind==='resources'"><label>年级<input v-model="filters.grade" maxlength="40" placeholder="全部年级"/></label><label>教材版本<input v-model="filters.textbook" maxlength="80" placeholder="不限版本"/></label><label>考试<input v-model="filters.exam" maxlength="80" placeholder="不限考试"/></label></template>
     <label v-if="kind==='mistakes'">查看范围<select v-model="filters.scope"><option v-if="session.user" value="mine">我的错题</option><option value="public">公开错题</option><option v-if="session.user" value="group">小组共享</option></select></label>
     <label v-if="kind==='mistakes'" class="check-label"><input v-model="filters.due" type="checkbox"/>待复习</label>
     <label v-else-if="session.user" class="check-label"><input v-model="filters.mine" type="checkbox"/>我创建的</label>
     <label v-if="['resources','collections'].includes(kind)&&session.user" class="check-label"><input v-model="filters.favorite" type="checkbox"/>我的收藏</label>
     <label v-if="kind==='collections'" class="check-label"><input v-model="filters.featured" type="checkbox"/>精选推荐</label>
     <label v-if="kind==='collections'&&session.user" class="check-label"><input v-model="filters.following" type="checkbox"/>我关注的</label>
     <button class="button" :disabled="loading" @click="page=1; load()">应用筛选</button><button v-if="kind==='resources'&&session.user" class="button" :disabled="busy" @click="showDownloads">下载记录</button>
    </div>
   </div>
   <section v-if="downloadsOpen" class="knowledge-panel"><h2>我的下载记录</h2><p v-for="record in downloads" :key="record.id"><RouterLink :to="'/resources/'+record.resource_id" class="text-button">{{ record.title }}</RouterLink> · {{ date(record.created_at) }}</p><p v-if="!downloads.length" class="muted">暂无下载记录。</p></section>
   <div v-if="editorOpen" class="knowledge-panel editor-panel">
    <div class="row-heading"><h2>{{ editingId?'编辑':'创建' }}{{ labels[kind] }}</h2><button v-if="!isNew" class="button" type="button" @click="editorOpen=false">取消</button><RouterLink v-else :to="'/'+kind" class="button">返回列表</RouterLink></div>
    <form @submit.prevent="save" class="knowledge-form">
     <label v-if="kind!=='mistakes'">标题<input v-model="form.title" required minlength="2" :maxlength="['collections','columns'].includes(kind)?120:160" placeholder="给知识一个清晰的标题"/></label>
     <label v-if="['resources','collections','columns'].includes(kind)">简介<textarea v-model="form.description" :required="kind==='resources'" :maxlength="kind==='resources'?10000:500" rows="3" placeholder="内容亮点、适合人群与使用方式"/></label>
     <div v-if="['resources','notes','mistakes','wiki'].includes(kind)" class="form-grid"><label>学科<input v-model="form.subject" :required="kind==='mistakes'" maxlength="40" placeholder="如：数学"/></label><label>标签<input v-model="form.tags" maxlength="500" placeholder="用逗号分隔，如：函数, 期中复习"/></label></div>
     <template v-if="kind==='resources'">
      <div class="form-grid"><label>年级<input v-model="form.grade" maxlength="40"/></label><label>教材版本<input v-model="form.textbook" maxlength="80"/></label><label>考试<input v-model="form.exam" maxlength="80"/></label><label>下载积分<input v-model.number="form.downloadPoints" type="number" required min="0" max="100"/></label></div>
      <label>来源<input v-model="form.source" required maxlength="255" placeholder="原创 / 来源名称与授权信息"/></label><label>版权说明<textarea v-model="form.copyrightNote" required maxlength="500" rows="3" placeholder="说明作者、授权范围或使用许可"/></label>
      <label class="upload-zone">选择资料文件<input type="file" multiple accept=".jpg,.jpeg,.png,.webp,.pdf,.txt,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.zip" :disabled="busy" @change="uploadFiles"/><small>图片、PDF、Office、TXT、ZIP；每个文件不超过 25MB，最多 10 个。</small></label>
      <ul class="file-list"><li v-for="(file,index) in files" :key="file.id">{{ file.name }} <small>{{ bytes(file.sizeBytes) }}</small><button type="button" class="text-button" @click="files.splice(index,1)">移除</button></li></ul>
      <div class="integrity-note"><ShieldCheck :size="20"/><p>仅分享拥有版权或获得授权的资料。请勿上传盗版教材、泄露试卷、代写内容或个人隐私；资料需审核后公开。</p></div>
      <label class="check-label"><input v-model="form.integrityAccepted" type="checkbox" required/>我确认有权分享此资料，并遵守版权与学术诚信要求。</label>
     </template>
     <template v-if="kind==='mistakes'">
      <label>题目<textarea v-model="form.question" required maxlength="10000" rows="5"/></label><label>答案与解析<textarea v-model="form.answer" required maxlength="10000" rows="5"/></label><label>错因分析<textarea v-model="form.reason" required maxlength="10000" rows="3" placeholder="概念混淆、计算失误或解题方法？"/></label>
      <div class="form-grid"><label>知识点<input v-model="form.knowledgePoint" maxlength="120"/></label><label>来源<input v-model="form.source" maxlength="255"/></label><label>关联帖子 ID（可选）<input v-model.number="form.postId" type="number" min="0"/></label><label>可见性<select v-model="form.visibility"><option value="private">仅自己（默认）</option><option value="public">公开</option><option value="group">小组共享</option></select></label></div>
      <label v-if="form.visibility==='group'">共享小组<select v-model.number="form.groupId" required><option :value="0" disabled>选择你加入的小组</option><option v-for="group in groups" :key="group.id" :value="group.id">{{ group.name }}</option></select></label>
      <label>题目图片<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="image($event,'imagePath')"/></label><img v-if="form.imagePath" :src="form.imagePath" class="knowledge-image" alt="题目图片预览"/>
     </template>
     <template v-if="kind==='notes'||wiki"><label v-if="wiki">关联帖子 ID（可选）<input v-model.number="form.postId" type="number" min="0"/></label><label>正文（支持 Markdown 标题、代码块）<textarea v-model="form.content" required maxlength="30000" rows="14" placeholder="从一个问题、一条术语或一段学习路线开始…"/></label><label>发布状态<select v-model="form.status"><option value="draft">保存草稿</option><option value="published">公开发布</option></select></label><p v-if="wiki" class="muted">每次修改保留版本。多人同时编辑时，系统会阻止覆盖他人的更新。</p></template>
     <template v-if="kind==='collections'||kind==='columns'"><label>封面（可选）<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="image($event,'coverUrl')"/></label><img v-if="form.coverUrl" :src="form.coverUrl" class="knowledge-cover" alt="封面预览"/></template>
     <button class="button primary" :disabled="busy||(kind==='resources'&&!files.length)">{{ busy?'处理中…':kind==='resources'?'提交审核':'保存' }}</button>
    </form>
   </div>
   <template v-if="!editorOpen">
    <div v-if="wiki" class="wiki-list"><article v-for="row in items" :key="row.id" class="knowledge-panel"><div class="row-heading"><div><span class="knowledge-chip">{{ statuses[row.status] }}</span><h2>{{ row.title }}</h2><p class="muted">维护者 {{ row.username }} · {{ date(row.updated_at) }}</p></div><div v-if="canWikiEdit" class="knowledge-actions"><button class="button" :disabled="busy" @click="openWiki(row)">编辑</button><button class="button" :disabled="busy" @click="revisions(row)"><History :size="15"/>历史</button></div></div><p v-if="row.tags" class="knowledge-tags">标签：{{ row.tags }}</p><RichContent :content="row.content"/><RouterLink v-if="row.post_id" :to="'/posts/'+row.post_id" class="button">关联讨论 →</RouterLink><RouterLink :to="{path:'/search',query:{q:row.title}}" class="text-button">查找相关讨论 →</RouterLink></article><p v-if="!items.length&&!loading" class="knowledge-empty">这个板块的 Wiki 还在等待第一位整理者。</p></div>
    <template v-else-if="!id">
     <div v-if="kind==='mistakes'&&session.user&&stats" class="knowledge-panel stats-panel"><h2>我的错题分布</h2><p class="muted">错误率 = 错误次数 ÷（错误次数 + 正确次数），包含初次记录的错误。</p><div class="stats-grid"><div v-for="s in stats.subjects" :key="s.subject"><strong>{{ s.total }}</strong><span>{{ s.subject }} · 错误率 {{ s.error_rate }}%</span></div></div><details v-if="stats.knowledgePoints?.length"><summary>按知识点查看</summary><ul><li v-for="s in stats.knowledgePoints" :key="s.subject+s.knowledge_point">{{ s.subject }} / {{ s.knowledge_point||'未标注' }}：{{ s.total }} 题 · 错误率 {{ s.error_rate }}%</li></ul></details></div>
     <div v-if="kind==='mistakes'&&filters.scope==='mine'&&items.length" class="knowledge-panel review-toolbar"><span>选择错题生成复习计划（已选 {{ selected.length }} 题）</span><label>周期 / 天<input v-model.number="reviewDays" type="number" min="1" max="90"/></label><button class="button primary" :disabled="busy||!selected.length" @click="makePlan">生成计划</button></div>
     <div class="knowledge-cards"><article v-for="row in items" :key="row.id" class="knowledge-card"><img v-if="row.cover_url" :src="row.cover_url" class="card-cover" alt="专题封面"/><div class="row-heading"><span class="knowledge-chip">{{ row.subject||labels[kind] }} <span v-if="row.is_featured">· 推荐</span></span><label v-if="kind==='mistakes'&&filters.scope==='mine'" class="check-label"><input v-model="selected" :value="row.id" type="checkbox" :aria-label="'选择错题 '+row.id"/>复习</label></div><RouterLink :to="'/'+kind+'/'+row.id" class="card-title"><h2>{{ row.title||(row.question?.slice(0,100)) }}</h2></RouterLink><p class="card-description">{{ row.description||row.reason||row.content }}</p><p v-if="row.tags" class="knowledge-tags">{{ row.tags }}</p><div class="card-meta"><span>{{ row.username }}</span><span>{{ date(row.created_at) }}</span><span v-if="row.visibility">{{ statuses[row.visibility] }}</span><span v-else-if="row.status!=='active'">{{ statuses[row.status] }}</span></div><div class="card-footer"><span v-if="kind==='resources'">{{ row.download_count }} 下载 · {{ row.favorite_count }} 收藏 · {{ row.download_points }} 积分</span><span v-else-if="kind==='collections'">{{ row.item_count }} 条目 · {{ row.follower_count }} 人关注</span><span v-else-if="kind==='mistakes'">下次复习：{{ row.next_review_date?date(row.next_review_date):'今天' }}</span><span v-else>继续阅读</span><RouterLink :to="'/'+kind+'/'+row.id" :aria-label="'阅读 '+(row.title||'错题')"><ArrowRight :size="18"/></RouterLink></div></article></div>
     <div v-if="!items.length&&!loading&&!error" class="knowledge-empty"><component :is="icons[kind]" :size="30"/><h2>这里还没有内容</h2><p>试试调整筛选，或整理你的第一份{{ labels[kind] }}。</p></div>
    </template>
    <article v-else-if="detail" class="knowledge-panel detail-panel">
     <RouterLink :to="'/'+kind" class="text-button">← 返回{{ labels[kind] }}</RouterLink><img v-if="detail.cover_url" :src="detail.cover_url" class="detail-cover" alt="专题封面"/><div class="row-heading"><div><span class="knowledge-chip">{{ detail.subject||labels[kind] }} · {{ statuses[detail.status||detail.visibility] }}</span><h2>{{ detail.title||(kind==='mistakes'?'错题 #'+id:'') }}</h2><p class="muted">{{ detail.username }} · {{ date(detail.created_at) }} <span v-if="detail.tags">· {{ detail.tags }}</span></p></div><button v-if="owner&&kind!=='resources'" class="button" @click="openEditor(detail)">编辑</button></div>
     <template v-if="kind==='resources'"><RichContent :content="detail.description"/><div class="metadata-grid"><span>学科：{{ detail.subject||'未分类' }}</span><span>年级：{{ detail.grade||'不限' }}</span><span>教材：{{ detail.textbook||'不限' }}</span><span>考试：{{ detail.exam||'不限' }}</span></div><p>来源：{{ detail.source }}</p><p>版权说明：{{ detail.copyright_note }}</p><div class="integrity-note"><ShieldCheck :size="20"/><p>资料仅用于合规学习。请尊重作者版权与学术诚信，不传播侵权内容。</p></div>
      <ul class="file-list"><li v-for="file in detail.files" :key="file.id"><FileText :size="18"/>{{ file.file_name }} <small>{{ bytes(file.size_bytes) }}</small><a v-if="owner||session.user?.role==='admin'" :href="'/api/resources/'+id+'/files/'+file.id" class="text-button">检查文件</a></li></ul>
      <div v-if="detail.status==='published'" class="knowledge-actions"><button class="button primary" :disabled="busy" @click="download"><Download :size="16"/>下载资料 · {{ detail.download_points }} 积分</button><button class="button" :disabled="busy" @click="action('/resources/'+id+'/favorite',{active:!detail.favorited})"><Bookmark :size="16"/>{{ detail.favorited?'取消收藏':'收藏' }} {{ detail.favorite_count }}</button><button class="button" :disabled="busy" @click="action('/resources/'+id+'/like',{active:!detail.liked})"><ThumbsUp :size="16"/>{{ detail.liked?'取消点赞':'点赞' }} {{ detail.like_count }}</button><button class="text-button" @click="login()&&(reportOpen=!reportOpen)">举报</button></div>
      <p class="muted">首次下载扣分，重复下载免费；上传者下载不扣分。下架后无法继续下载。</p><div v-if="downloadFiles.length" class="download-list"><a v-for="file in downloadFiles" :key="file.id" :href="'/api/resources/'+id+'/files/'+file.id" class="button"><Download :size="16"/>保存 {{ file.file_name }}</a></div>
      <form v-if="reportOpen" class="knowledge-form" @submit.prevent="sendReport"><label>举报原因<select v-model="reportReason"><option>抄袭侵权</option><option>广告垃圾</option><option>学术不端</option><option>其他</option></select></label><label>补充说明<textarea v-model="reportDescription" maxlength="500" rows="3"/></label><button class="button" :disabled="busy">提交举报</button></form>
      <section class="comments-section"><h3>资料讨论</h3><form v-if="detail.status==='published'" @submit.prevent="sendComment" class="knowledge-form"><label>写一条评论<textarea v-model="comment" maxlength="1000" rows="3" required placeholder="分享使用体验，或补充资料说明"/></label><button class="button" :disabled="busy">发布评论</button></form><article v-for="c in detail.comments" :key="c.id" class="comment-row"><b>{{ c.username }}</b> <small>{{ date(c.created_at) }}</small><p>{{ c.content }}</p></article><p v-if="!detail.comments.length" class="muted">暂无评论，欢迎分享你的使用体验。</p></section>
     </template>
     <template v-else-if="kind==='mistakes'"><h3>题目</h3><RichContent :content="detail.question"/><img v-if="detail.image_path" :src="'/api/mistakes/'+id+'/image'" class="knowledge-image" alt="错题题目"/><details class="answer-panel"><summary>查看答案与解析</summary><RichContent :content="detail.answer"/></details><h3>错因分析</h3><RichContent :content="detail.reason"/><p>知识点：{{ detail.knowledge_point||'未标注' }} · 来源：{{ detail.source||'未标注' }}</p><RouterLink v-if="detail.post_id" :to="'/posts/'+detail.post_id" class="button">查看关联讨论 →</RouterLink><div v-if="owner" class="knowledge-actions"><button class="button primary" :disabled="busy" @click="action('/mistakes/'+id+'/review',{result:'correct'},'已记录掌握情况')">我答对了</button><button class="button" :disabled="busy" @click="action('/mistakes/'+id+'/review',{result:'incorrect'},'已加入下一轮复习')">还需练习</button></div><p class="muted">累计错误 {{ detail.error_count }} 次，正确 {{ detail.correct_count }} 次 · 下次复习 {{ detail.next_review_date?date(detail.next_review_date):'今天' }}</p><details v-if="owner&&detail.reviews?.length"><summary>复习记录</summary><p v-for="r in detail.reviews" :key="r.id">{{ date(r.reviewed_at) }} · {{ r.result==='correct'?'答对了':'仍有错误' }}</p></details></template>
     <template v-else-if="kind==='notes'"><RichContent :content="detail.content"/><button v-if="owner" class="button" :disabled="busy" @click="revisions()"><History :size="15"/>版本历史</button></template>
     <template v-else-if="kind==='collections'"><p>{{ detail.description }}</p><div class="knowledge-actions"><button class="button" :disabled="busy" @click="action('/collections/'+id+'/follow',{active:!detail.followed})">{{ detail.followed?'取消关注':'关注合集' }}</button><button class="button" :disabled="busy" @click="action('/collections/'+id+'/favorite',{active:!detail.favorited})">{{ detail.favorited?'取消收藏':'收藏合集' }}</button><button class="button" :disabled="busy" @click="share">复制分享链接</button><button v-if="owner" class="button primary" :disabled="busy" @click="pickerOpen=!pickerOpen">添加条目</button></div>
      <form v-if="pickerOpen" class="knowledge-form" @submit.prevent="addItem"><div class="form-grid"><label>内容类型<select v-model="picker.type" @change="choices=[];picker.id=0"><option value="post">帖子</option><option value="resource">资料</option><option value="note">笔记</option></select></label><label>搜索内容<input v-model="picker.q" maxlength="100"/></label></div><button class="button" type="button" :disabled="busy" @click="searchPicker">查找可收录内容</button><label>选择条目<select v-model.number="picker.id" required><option :value="0" disabled>请选择（仅已发布内容）</option><option v-for="r in choices" :key="r.id" :value="r.id">{{ r.title }}</option></select></label><label>排序（数字小的在前）<input v-model.number="picker.sortOrder" type="number" min="0" max="10000"/></label><button class="button primary" :disabled="busy||!picker.id">收录</button></form>
      <ol class="collection-list"><li v-for="item in detail.items" :key="item.id"><span class="knowledge-chip">{{ {post:'帖子',resource:'资料',note:'笔记'}[item.item_type as 'post'|'resource'|'note'] }}</span><RouterLink :to="target(item)">{{ item.title }}</RouterLink><div v-if="owner" class="item-controls"><input v-model.number="item.sort_order" type="number" min="0" max="10000" :aria-label="'条目 '+item.title+' 的排序'"/><button class="text-button" :disabled="busy" @click="itemChange(item)">保存排序</button><button class="text-button" :disabled="busy" @click="itemChange(item,true)">移除</button></div></li></ol><p v-if="!detail.items.length" class="knowledge-empty">暂无可见条目，已下架内容会自动隐藏。</p>
     </template>
     <template v-else-if="kind==='columns'"><p>{{ detail.description }}</p><button v-if="owner" class="button primary" :disabled="busy" @click="openEpisode()">发布新一期</button>
      <form v-if="episodeOpen" @submit.prevent="saveEpisode" class="knowledge-form episode-editor"><h3>{{ episodeEditingId?'编辑连载':'新增连载' }}</h3><div class="form-grid"><label>期数<input v-model.number="episode.episodeNo" type="number" required min="1" max="10000" :disabled="!!episodeEditingId"/></label><label>状态<select v-model="episode.status"><option value="published">公开发布</option><option value="draft">草稿</option></select></label></div><label v-if="!episodeEditingId">从我的已发布笔记导入（可选）<select v-model.number="episode.noteId"><option :value="0">直接撰写</option><option v-for="note in notesOptions" :key="note.id" :value="note.id">{{ note.title }}</option></select></label><template v-if="!episode.noteId"><label>本期标题<input v-model="episode.title" required minlength="2" maxlength="160"/></label><label>本期正文<textarea v-model="episode.content" required maxlength="30000" rows="12"/></label></template><div class="knowledge-actions"><button class="button primary" :disabled="busy">保存连载</button><button type="button" class="button" @click="episodeOpen=false">取消</button></div></form>
      <section v-for="row in detail.episodes" :key="row.id" class="episode-panel"><span class="eyebrow">第 {{ row.episode_no }} 期 · {{ statuses[row.status] }}</span><h3>{{ row.title }}</h3><RichContent :content="row.content"/><button v-if="owner" class="button" :disabled="busy" @click="openEpisode(row)">编辑本期</button></section><p v-if="!detail.episodes.length" class="knowledge-empty">连载尚未开始。</p>
     </template>
    </article>
   </template>
  </template>
  <section v-if="historyOpen" class="knowledge-panel history-panel"><div class="row-heading"><h2>版本历史</h2><button class="button" @click="historyOpen=false">收起</button></div><details v-for="r in history" :key="r.id"><summary>#{{ r.id }} · {{ r.title }} · {{ r.username||'我' }} · {{ date(r.created_at) }}</summary><RichContent :content="r.content"/></details><p v-if="!history.length">暂无历史版本。</p></section>
